"""Train FLOODGUARD water-level forecasting models (Phase 3).

What is real and what is not
----------------------------
* REAL: the rainfall forcing series comes from the IMD gridded files, read from
  the compact artefact produced by `preprocess_data.py`.
* SIMULATED: the 5-minute water-level series is generated by a documented
  single-reservoir (storage-routing) model driven by that rainfall. The project
  has no year of 5-minute gauge records, so training levels must be synthesised.
  Every artefact and every metric written by this script is labelled accordingly
  and the UI must present results as prototype-grade, not operational.

Feature order is fixed by `forecast_service._build_features`; the first feature
MUST be `current_level` because the persistence baseline indexes x[0].

Time-series discipline: the split is chronological. Nothing is shuffled.
"""

from __future__ import annotations

import asyncio
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

import joblib
import numpy as np

BACKEND_ROOT = Path(__file__).resolve().parents[1]
REPO_ROOT = BACKEND_ROOT.parent
sys.path.insert(0, str(BACKEND_ROOT))

from app.core.config import get_settings  # noqa: E402

STEP_MINUTES = 5
HORIZONS = [15, 30, 60]
STEPS_PER_DAY = 24 * 60 // STEP_MINUTES

# Reservoir parameters for the Mithi corridor. Chosen so that a design storm of
# ~80 mm/day produces a stage rise in the same order as the observed corridor,
# not fitted to any specific event.
BASE_LEVEL_CM = 120.0
STORAGE_K = 0.55  # outflow coefficient (per step)
STORAGE_X = 0.30  # dimensionless storage-release exponent
DRAINAGE_MM_HR = 6.0  # steady drainage/outflow rate
SOIL_CAPACITY_MM = 45.0  # soil storage before runoff coefficient rises
DESIGN_PEAK_CM = 245.0  # stage the 99th-percentile storm maps to

FEATURE_ORDER = [
    "current_level",
    "prev_level_1",
    "prev_level_2",
    "prev_level_3",
    "prev_level_6",
    "current_rainfall",
    "avg_rainfall_1h",
    "rainfall_trend",
    "rise_rate",
    "level_std",
    # Appended by forecast_service._build_features' caller from the node's
    # upstream relationship. MUST be trained on or sklearn rejects the vector.
    "upstream_level_cm",
]


def log(msg: str) -> None:
    print(f"[train] {msg}", flush=True)


def load_imd_rainfall() -> tuple[list[float], list[str]]:
    """Return the daily rainfall series (mm/day) from the processed IMD file."""
    settings = get_settings()
    path = settings.resolve_data_path(settings.imd_processed_dir) / "mumbai_rainfall.json"
    if not path.exists():
        raise SystemExit(
            "IMD artefact missing. Run: python -m scripts.preprocess_data --skip-dem --skip-osm"
        )
    payload = json.loads(path.read_text(encoding="utf-8"))

    by_date: dict[str, float] = {}
    for year in payload["years"]:
        for date_str, value in zip(year["dates"], year["daily_mm"]):
            if value is None:
                continue
            by_date[date_str.split("T")[0].split(" ")[0]] = float(value)

    dates = sorted(by_date)
    log(f"IMD rainfall: {len(dates)} days from {dates[0]} to {dates[-1]}")
    return [by_date[d] for d in dates], dates


def build_subdaily_rainfall(daily_mm: list[float], rng: np.random.Generator) -> np.ndarray:
    """Disaggregate daily totals into a 5-minute intensity series.

    A daily total cannot be spread uniformly: real monsoon bursts are strongly
    concentrated. This uses a fixed diurnal shape (peaking late afternoon) with
    a gamma-distributed multiplier, then rescales each day so the daily total is
    preserved exactly. The shape is a modelling assumption, not measured data.
    """
    hours = np.arange(STEPS_PER_DAY) * STEP_MINUTES / 60.0
    # Late-afternoon convective peak typical of the Mumbai monsoon.
    diurnal = 0.35 + np.exp(-(((hours - 16.0) / 3.2) ** 2))
    diurnal = diurnal / diurnal.sum()

    out = np.empty(len(daily_mm) * STEPS_PER_DAY)
    for i, total in enumerate(daily_mm):
        shape = diurnal * rng.gamma(shape=1.6, scale=1.0, size=STEPS_PER_DAY)
        total_shape = shape.sum()
        # gamma() can draw an all-zero vector; fall back to the diurnal shape so
        # the day never becomes 0/0 -> NaN.
        if not np.isfinite(total_shape) or total_shape <= 0:
            shape = diurnal.copy()
            total_shape = shape.sum()
        shape = shape / total_shape
        out[i * STEPS_PER_DAY : (i + 1) * STEPS_PER_DAY] = shape * total
    return np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)


def simulate_storage(rain_mm_5min: np.ndarray) -> np.ndarray:
    """Run the reservoir to get a 5-minute storage series (mm)."""
    n = len(rain_mm_5min)
    storage_series = np.empty(n)
    storage = 0.0
    soil = 0.0

    for i in range(n):
        rain_mm_hr = rain_mm_5min[i] * (60.0 / STEP_MINUTES)

        # Soil store fills first; once saturated, runoff approaches rainfall.
        soil += rain_mm_hr / 12.0
        runoff_frac = min(1.0, soil / SOIL_CAPACITY_MM)
        effective = rain_mm_hr * runoff_frac
        soil = max(0.0, soil - rain_mm_hr / 12.0 * 0.55)

        inflow = effective * STEP_MINUTES / 60.0  # mm this step
        outflow = (DRAINAGE_MM_HR + STORAGE_K * max(storage, 0.0) ** STORAGE_X) * STEP_MINUTES / 60.0
        storage = max(0.0, storage + inflow - outflow)
        storage_series[i] = storage

    return np.nan_to_num(storage_series, nan=0.0, posinf=0.0, neginf=0.0)


def storage_to_levels(storage: np.ndarray, rng: np.random.Generator) -> np.ndarray:
    """Map storage to stage in cm.

    A fixed coefficient pins extreme monsoon bursts against the clamp, which
    teaches the models a saturated series. Instead the mapping is calibrated on
    this run's own storage distribution so the design peak lands at a plausible
    corridor stage and the response stays monotone.
    """
    p50 = float(np.percentile(storage, 50))
    p99 = float(np.percentile(storage, 99))
    span = max(p99 - p50, 1e-6)

    # Normalise storage into 0..1 against the observed range, then apply a mild
    # concave curve (channel widening with stage).
    norm = np.clip((storage - p50) / span, 0.0, 1.0)
    swing = DESIGN_PEAK_CM - BASE_LEVEL_CM
    target = BASE_LEVEL_CM + swing * norm**0.7

    # Routing lag so the stage responds over several steps rather than instantly.
    level = BASE_LEVEL_CM
    out = np.empty(len(target))
    for i, t in enumerate(target):
        level = 0.72 * level + 0.28 * t
        out[i] = max(0.0, min(400.0, level + rng.normal(0.0, 0.18)))

    return np.nan_to_num(out, nan=BASE_LEVEL_CM, posinf=BASE_LEVEL_CM, neginf=BASE_LEVEL_CM)


def build_dataset(
    levels: np.ndarray,
    rainfall: np.ndarray,
    horizon_steps: int,
    upstream: np.ndarray | None = None,
):
    """Build the supervised matrix using the service's exact feature order."""
    rows, targets = [], []
    # Start at 11 so rainfall[i-11:i+1] is a real 12-sample (1 hour) window;
    # a negative start index silently yields an empty slice and a NaN mean.
    for i in range(11, len(levels) - horizon_steps):
        lvl = levels[i - 5 : i + 1]
        rain = rainfall[i - 11 : i + 1]
        up = float(upstream[i]) if upstream is not None else 0.0
        rows.append(
            [
                levels[i],
                levels[i - 1],
                levels[i - 2],
                levels[i - 3],
                levels[i - 6],
                rainfall[i],
                float(np.mean(rain)),
                float(rainfall[i] - rainfall[i - 1]),
                float(levels[i] - levels[i - 1]),
                float(np.std(lvl)),
                up,
            ]
        )
        targets.append(levels[i + horizon_steps])
    X = np.nan_to_num(np.asarray(rows, dtype=float), nan=0.0, posinf=0.0, neginf=0.0)
    y = np.nan_to_num(np.asarray(targets, dtype=float), nan=BASE_LEVEL_CM)
    return X, y


class PersistenceModel:
    """Baseline: future level equals current level (x[0])."""

    def predict(self, X):
        return np.array([row[0] for row in X])


def metrics(y_true: np.ndarray, y_pred: np.ndarray) -> tuple[float, float]:
    err = y_true - y_pred
    return float(np.mean(np.abs(err))), float(np.sqrt(np.mean(err**2)))


async def train() -> int:
    from sklearn.ensemble import RandomForestRegressor
    from sklearn.linear_model import LinearRegression

    settings = get_settings()
    rng = np.random.default_rng(20240115)  # fixed seed -> reproducible artefacts

    daily_mm, dates = load_imd_rainfall()
    rain_5min = build_subdaily_rainfall(daily_mm, rng)
    storage = simulate_storage(rain_5min)
    levels = storage_to_levels(storage, rng)

    # A second, slightly lagged series stands in for the upstream neighbour so
    # the `upstream_level_cm` feature carries the same meaning it will at
    # inference time, instead of being a constant zero the model ignores.
    upstream_rain = np.concatenate([np.zeros(4), rain_5min[:-4]])
    upstream_levels = storage_to_levels(simulate_storage(upstream_rain), rng)

    log(
        f"simulated series: {len(levels)} steps "
        f"({len(levels) / STEPS_PER_DAY:.0f} days) "
        f"level min={levels.min():.1f} max={levels.max():.1f} cm"
    )

    model_dir = settings.resolve_data_path(settings.flood_model_dir)
    model_dir.mkdir(parents=True, exist_ok=True)

    report: dict = {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "rainfall_source": "IMD gridded rainfall (real observations)",
        "level_source": (
            "SIMULATED single-reservoir storage-routing model driven by IMD rainfall. "
            "Not measured gauge data."
        ),
        "step_minutes": STEP_MINUTES,
        "rainfall_period": f"{dates[0]} to {dates[-1]}",
        "feature_order": FEATURE_ORDER,
        "split": "chronological 70/15/15 (no shuffling)",
        "reservoir_parameters": {
            "base_level_cm": BASE_LEVEL_CM,
            "storage_k": STORAGE_K,
            "storage_x": STORAGE_X,
            "drainage_mm_hr": DRAINAGE_MM_HR,
            "soil_capacity_mm": SOIL_CAPACITY_MM,
        },
        "horizons": {},
        "limitations": [
            "Training levels are simulated, so reported skill is optimistic relative to real gauges.",
            "Sub-daily rainfall shape is a modelling assumption (gamma + diurnal), not measured.",
            "Single reservoir: no channel routing, backwater or tide.",
            "Prototype only; not validated for operational flood forecasting.",
        ],
    }

    for horizon in HORIZONS:
        steps = horizon // STEP_MINUTES
        X, y = build_dataset(levels, rain_5min, steps, upstream_levels)
        n = len(X)
        i1, i2 = int(n * 0.70), int(n * 0.85)
        X_tr, y_tr = X[:i1], y[:i1]
        X_va, y_va = X[i1:i2], y[i1:i2]
        X_te, y_te = X[i2:], y[i2:]

        base = PersistenceModel()
        base_mae, base_rmse = metrics(y_te, base.predict(X_te))

        linear = LinearRegression().fit(X_tr, y_tr)
        lin_mae, lin_rmse = metrics(y_te, linear.predict(X_te))

        rf = RandomForestRegressor(
            n_estimators=300,
            max_depth=14,
            min_samples_leaf=5,
            random_state=42,
            n_jobs=-1,
        )
        rf.fit(X_tr, y_tr)
        rf_mae, rf_rmse = metrics(y_te, rf.predict(X_te))
        rf_mae_val, rf_rmse_val = metrics(y_va, rf.predict(X_va))

        # Ship RF only if it beats persistence on the test split, otherwise the
        # service falls back to the baseline and the UI says so.
        skill = (base_mae - rf_mae) / base_mae * 100.0
        use_rf = rf_mae < base_mae

        bundle = {
            "model": rf if use_rf else PersistenceModel(),
            "algorithm": "random_forest" if use_rf else "persistence",
            "feature_order": FEATURE_ORDER,
            "horizon_minutes": horizon,
            "trained_at": report["generated_at"],
            "metrics": {
                "mae": rf_mae if use_rf else base_mae,
                "rmse": rf_rmse if use_rf else base_rmse,
                "baseline_mae": base_mae,
                "baseline_rmse": base_rmse,
            },
            "level_source": report["level_source"],
        }
        path = model_dir / f"rf_{horizon}min.joblib"
        joblib.dump(bundle, path)

        report["horizons"][f"{horizon}min"] = {
            "artifact": str(path.relative_to(REPO_ROOT)),
            "samples": int(n),
            "train": int(len(X_tr)),
            "test": int(len(X_te)),
            "persistence_mae_cm": round(base_mae, 3),
            "persistence_rmse_cm": round(base_rmse, 3),
            "linear_mae_cm": round(lin_mae, 3),
            "linear_rmse_cm": round(lin_rmse, 3),
            "random_forest_mae_cm": round(rf_mae, 3),
            "random_forest_rmse_cm": round(rf_rmse, 3),
            "rf_val_mae_cm": round(rf_mae_val, 3),
            "rf_val_rmse_cm": round(rf_rmse_val, 3),
            "skill_vs_persistence_pct": round(skill, 1),
            "shipped": bundle["algorithm"],
        }
        log(
            f"{horizon:>3}min  persistence MAE={base_mae:6.3f}  "
            f"RF MAE={rf_mae:6.3f}  skill={skill:+6.1f}%  "
            f"shipped={bundle['algorithm']}"
        )

    meta = model_dir / "model_metadata.json"
    meta.write_text(json.dumps(report, indent=2), encoding="utf-8")
    log(f"wrote {meta.relative_to(REPO_ROOT)}")

    await register_in_db(report, model_dir)
    return 0


async def register_in_db(report: dict, model_dir: Path) -> None:
    """Upsert ModelRegistry rows so /api/about/model-info reports real metrics."""
    import asyncio

    from sqlalchemy import select

    from app.core.database import AsyncSessionLocal
    from app.models.floodguard import ModelRegistry

    version = datetime.now(timezone.utc).strftime("%Y%m%d%H%M")
    description = (
        "Rainfall forcing: real IMD gridded daily observations. "
        "Training levels: SIMULATED single-reservoir storage-routing series at 5-minute "
        "steps. Chronological 70/15/15 split, no shuffling. Prototype grade."
    )

    async with AsyncSessionLocal() as db:
        for horizon in HORIZONS:
            key = f"{horizon}min"
            stats = report["horizons"][key]
            row = (
                await db.execute(
                    select(ModelRegistry).where(
                        ModelRegistry.horizon_minutes == horizon,
                        ModelRegistry.is_active == True,  # noqa: E712
                    )
                )
            ).scalars().first()

            fields = {
                "model_name": f"rf_15_30_60_{key}" if stats["shipped"] == "random_forest" else f"persistence_{key}",
                "version": f"rf-v1-{version}",
                "algorithm": stats["shipped"],
                "artifact_path": str((model_dir / f"rf_{horizon}min.joblib").resolve()),
                "training_data_description": description,
                "mae": stats["random_forest_mae_cm"] if stats["shipped"] == "random_forest" else stats["persistence_mae_cm"],
                "rmse": stats["random_forest_rmse_cm"] if stats["shipped"] == "random_forest" else stats["persistence_rmse_cm"],
                "baseline_mae": stats["persistence_mae_cm"],
                "baseline_rmse": stats["persistence_rmse_cm"],
                "trained_at": datetime.now(timezone.utc),
                "is_active": True,
            }

            if row is None:
                db.add(ModelRegistry(horizon_minutes=horizon, **fields))
            else:
                for k, v in fields.items():
                    setattr(row, k, v)

        await db.commit()
        log("registered model metadata in database")


if __name__ == "__main__":
    raise SystemExit(asyncio.run(train()))